window.COURSES.push(
{ id:"pe01", cat:"people", e:"💬", title:"Small Talk That Works", sub:"Turn awkward openers into real conversation", cards:[
 {e:"🚪", h:"Small talk is a doorway", t:"Small talk is not the point; it is the door. People use easy topics to check whether you are safe and friendly before sharing more. Treat the weather chat as a warm-up, not a waste of time."},
 {e:"🎯", h:"Use the surroundings", t:"The easiest opener is whatever you both share right now. Comment on the event, the food, the room. Example: 'How do you know the host?' works at almost any party and invites a story instead of a yes or no."},
 {e:"❓", h:"Ask open questions", t:"Closed questions get one-word answers. Open ones start with what, how, or tell me about. Swap 'Did you have a good weekend?' for 'What was the best part of your weekend?' and watch the answer grow.", list:["What got you into that?","How did you end up here?","What are you looking forward to?"]},
 {e:"🔁", h:"Follow the thread", t:"Listen for a detail in their answer and ask about it. If they mention moving cities, ask what surprised them most. Following one thread beats a list of prepared questions, because it proves you actually heard them."},
 {e:"🪞", h:"Share, don't just interview", t:"A string of questions feels like an interrogation. After they answer, add a short piece of your own. Example: 'I also tried climbing last year, I was terrible but loved it.' Give and take keeps the balance fair."},
 {e:"⭐", h:"Find the common ground", t:"Rapport grows from shared experiences, interests, or even shared complaints about a delayed train. When you spot overlap, name it warmly: 'Oh, you like hiking too? Where do you usually go?'", stat:{n:"1 in 3", l:"people say small talk with strangers makes them happier than they expected"}},
 {e:"🚀", h:"Go one level deeper", t:"Move from facts to feelings with a gentle step. After hearing about their job, ask 'What do you enjoy most about it?' Opinions and enthusiasm reveal personality far faster than job titles do."},
 {e:"👋", h:"Exit gracefully", t:"Ending well matters as much as starting. Be honest, warm, and specific, then leave. Never invent an excuse you will regret. A clean close makes people want to talk to you again.", list:["It was great meeting you, enjoy the night.","I am going to grab a drink, good talking.","Let us swap numbers and continue this."]}
], quiz:[
 {q:"Which question best invites a longer answer?", o:["Did you like the event?","What was the best part of the event for you?","Was the event good?"], a:1, w:"Open questions starting with 'what' invite stories rather than yes or no."},
 {q:"What should you do after someone mentions a detail?", o:["Change the topic","Ignore it and use your next prepared question","Ask more about that detail"], a:2, w:"Following the thread shows you listened and keeps the conversation flowing."},
 {q:"Why share something about yourself during small talk?", o:["It balances the exchange so it does not feel like an interview","To steer the talk toward your own interests only","To end the conversation faster"], a:0, w:"Mutual sharing creates fairness and trust."},
 {q:"What is a good way to leave a conversation?", o:["Disappear without saying anything","Make up a dramatic emergency","Say something warm and honest, then go"], a:2, w:"A friendly, honest close leaves a positive final impression."}
]},
{ id:"pe02", cat:"people", e:"👂", title:"Active Listening", sub:"Make people feel truly heard", cards:[
 {e:"🎧", h:"Listening is a skill", t:"Most people listen to reply, not to understand. Active listening means giving your full attention first and forming a response second. It is learnable, and it is rare enough to make you stand out immediately."},
 {e:"📵", h:"Remove the distractions", t:"Put the phone face down, turn toward the person, and quiet your inner monologue. Even a visible phone on the table can reduce how connected a conversation feels. Attention is the first gift you give.", stat:{n:"~60%", l:"of people rate their own listening as above average, so most overrate themselves"}},
 {e:"🔄", h:"Paraphrase back", t:"Restate what you heard in your own words before responding. Example: 'So the deadline moved and you are worried about the handoff, is that right?' It catches misunderstandings and signals real care."},
 {e:"🧩", h:"Reflect the feeling", t:"Name the emotion under the facts. 'That sounds frustrating' or 'You seem really proud of that' tells people their inner experience landed. Guess gently and let them correct you if you are off."},
 {e:"⏸️", h:"Embrace the pause", t:"After someone finishes, wait two or three seconds. Silence often invites them to add the real thing they were holding back. Resist filling every gap with advice or your own story."},
 {e:"🙊", h:"Do not fix too soon", t:"Jumping to solutions can feel dismissive. Ask first: 'Do you want advice, or do you mostly want me to listen?' That one question prevents countless small hurts.", list:["Do you want ideas or just an ear?","Tell me more about that.","What would help most right now?"]},
 {e:"✋", h:"Do not hijack the story", t:"When someone shares a struggle, resist 'that happened to me too' followed by a ten-minute tale. Briefly relate if it helps, then hand the spotlight straight back with a question."},
 {e:"🌱", h:"Ask follow-up questions", t:"Good follow-ups show you were tracking. 'What happened next?' and 'How did that feel?' deepen the talk naturally. Aim for curiosity, not for sounding clever."}
], quiz:[
 {q:"What does paraphrasing do?", o:["Shows off your vocabulary","Confirms understanding and signals care","Lets you avoid answering"], a:1, w:"Restating helps catch misunderstandings and shows attention."},
 {q:"When a friend shares a problem, what is a good first move?", o:["Ask whether they want advice or just listening","Immediately list solutions","Share a bigger problem of yours"], a:0, w:"Checking what they need prevents unwanted fixing."},
 {q:"Why pause after someone stops speaking?", o:["To look thoughtful for its own sake","To give them space to add something deeper","To check your phone"], a:1, w:"Silence often draws out the most meaningful part."},
 {q:"What is conversational hijacking?", o:["Asking too many questions","Making eye contact","Turning their story into yours"], a:2, w:"Redirecting the spotlight to yourself leaves them unheard."}
]},
{ id:"pe03", cat:"people", e:"🧍", title:"Body Language Basics", sub:"Read and send clearer signals", cards:[
 {e:"📡", h:"Signals travel in clusters", t:"One gesture means little. Crossed arms might mean cold, not defensive. Look for clusters of cues plus context, and compare against the person's normal baseline before drawing any conclusion about them."},
 {e:"👀", h:"Eye contact in balance", t:"Hold eye contact roughly half to two thirds of the time while listening, and look away briefly to think. Constant staring feels intense; constant avoidance feels evasive. Aim for relaxed and warm."},
 {e:"😊", h:"A real smile reaches eyes", t:"Genuine smiles engage the muscles around the eyes, not just the mouth. You cannot fake it well, but you can feel real warmth by recalling something you genuinely like about the person."},
 {e:"🧭", h:"Orient your body", t:"People tend to point their feet and torso toward what interests them. Face the person you are talking to with your whole body. Turning slightly away can signal you want to leave."},
 {e:"🪑", h:"Open posture, calm space", t:"Keep shoulders back and relaxed, hands visible, and avoid hiding behind bags or crossed arms when you want to seem approachable. Take up appropriate space without sprawling or shrinking."},
 {e:"🤝", h:"Handshake and touch", t:"Offer a firm but not crushing handshake with a brief smile and eye contact. Norms about touch vary by culture and person, so follow their lead and respect any sign they prefer distance."},
 {e:"🔊", h:"Your voice is body language", t:"Pace, pitch, and volume speak too. Slowing down and lowering your pitch at the end of sentences sounds calm and confident. Rushed, rising tones can make statements sound like questions."},
 {e:"🔍", h:"Notice, then ask", t:"Treat body language as a prompt, not a verdict. If someone's face tightens, check in kindly rather than assuming. 'You seem a bit unsure, anything I can clarify?' keeps you accurate and respectful.", list:["Notice the change","Hold it as a guess","Ask kindly to confirm"]}
], quiz:[
 {q:"How should you interpret a single gesture?", o:["As proof of lying","As one clue to read with context and cluster","As meaningless"], a:1, w:"Single cues are unreliable; clusters and context matter."},
 {q:"What does a genuine smile engage?", o:["Only the mouth","The forehead","The muscles around the eyes too"], a:2, w:"Real smiles crinkle the eyes as well as lift the mouth."},
 {q:"What is a healthy way to use body language readings?", o:["As a prompt to check in gently","As a verdict to confront them","To prove you are right"], a:0, w:"Reads are guesses; asking confirms them respectfully."},
 {q:"Which posture tends to seem most approachable?", o:["Arms crossed behind a bag","Open, relaxed shoulders and visible hands","Turned slightly away"], a:1, w:"Open posture signals ease and friendliness."}
]},
{ id:"pe04", cat:"people", e:"🧑‍🤝‍🧑", title:"Making Friends as an Adult", sub:"Build a circle from scratch", cards:[
 {e:"🔁", h:"Repeated contact wins", t:"Friendships mostly grow from repeated, unplanned time together. That is why school made it easy. Choose a weekly class, club, or team so familiar faces turn into friends without forcing anything.", stat:{n:"~50 hrs", l:"of time together is often cited to move from acquaintance to casual friend (Hall, 2018)"}},
 {e:"🎯", h:"Go where your people are", t:"Join something built around an interest you actually enjoy: climbing gym, book club, volunteering, board games. Shared activity gives you built-in conversation and removes pressure to perform socially."},
 {e:"📅", h:"Be the one who invites", t:"Many people wait to be asked. Take the first step with something small and specific. Example: 'A few of us are grabbing coffee after class on Saturday, want to join?' Low stakes, clear plan."},
 {e:"🧲", h:"Expect some rejection", t:"Not every invite lands, and that rarely reflects on you; people are busy. Try again once without pressure. Persistence in a light tone often turns a 'maybe' into a regular hangout."},
 {e:"🔔", h:"Follow up within days", t:"After a good first chat, message within a couple of days while it is fresh. 'Really enjoyed talking about hiking, want to try that trail next weekend?' Momentum fades quickly if you wait."},
 {e:"🌉", h:"Turn acquaintances up", t:"Move from group settings to one-on-one gradually. Invite one person from the group to something small. One-on-one time lets stories and trust develop that crowded rooms rarely allow."},
 {e:"🎁", h:"Be a giver of attention", t:"Remember names, ask about their kid's recital, check in after their interview. Small acts of noticing build warmth faster than clever lines. Reliability beats charisma for lasting friendship."},
 {e:"🕰️", h:"Give it a real timeline", t:"Plan on months, not weeks. Treat it as a project with steady effort: aim for two or three social touchpoints per week. Patience prevents you from quitting right before it starts to work."}
], quiz:[
 {q:"What most helps acquaintances become friends?", o:["Perfect jokes","A big dramatic gesture","Repeated time together"], a:2, w:"Repeated contact builds familiarity and trust."},
 {q:"What is a good invite?", o:["Small, specific, low pressure","Vague and open-ended","A huge event"], a:0, w:"Clear small plans are easy to say yes to."},
 {q:"If someone declines an invite, you should?", o:["Assume they dislike you","Try again lightly once or twice","Stop talking to them forever"], a:1, w:"Busy schedules are common; a light retry often works."},
 {q:"When should you follow up after a good chat?", o:["Within a few days","After a month","Never, wait for them"], a:0, w:"Fresh momentum makes reconnecting easy."}
]},
{ id:"pe05", cat:"people", e:"✨", title:"The Charisma Myth", sub:"Presence, power and warmth (Olivia Fox Cabane)", cards:[
 {e:"🧪", h:"Charisma can be learned", t:"Cabane argues charisma is a set of behaviors, not a birth gift. It grows from three ingredients: presence, power, and warmth. Practice each one and others begin to find you magnetic."},
 {e:"🎯", h:"Presence means being here", t:"Presence is giving full attention to the person in front of you. People can feel when your mind wanders. Try anchoring with your senses for a moment before you talk: feel your feet, notice the room."},
 {e:"🕐", h:"The ten second reset", t:"If your thoughts drift mid-conversation, do a quick reset. Feel your feet on the floor, take one breath, and refocus on their words. Returning gently beats beating yourself up for drifting.", list:["Feel your feet","Take one slow breath","Return to their words"]},
 {e:"💪", h:"Power is perceived ability", t:"Power in this sense means influence or capability, shown by calm posture, a steady pace, and not over-apologizing. You do not need a title, only a grounded way of carrying yourself."},
 {e:"🔥", h:"Warmth is goodwill", t:"Warmth is the sense that you care about the other person. It shows in genuine smiles, attentive eyes, and kind tone. Power without warmth feels cold; warmth without power can seem easy to dismiss."},
 {e:"⚖️", h:"Blend them for context", t:"Different moments call for different mixes. Use more warmth when comforting a friend, more power when presenting plans. Flexing between them is what makes charismatic people feel adaptable."},
 {e:"🌧️", h:"Handle the inner critic", t:"Self-judgment steals presence. Notice a harsh thought, label it as 'just a thought,' and let it pass without arguing. Treating it as noise stops it from running your body language."},
 {e:"🎬", h:"Prepare, then practice", t:"Visualize a specific upcoming conversation going well, then rehearse key lines aloud. Preparation lowers anxiety, which frees your attention for the other person, and attention is where charisma lives."}
], quiz:[
 {q:"What are the three components of charisma in the book?", o:["Humor, looks, wealth","Presence, power, warmth","Speed, volume, confidence"], a:1, w:"Cabane identifies presence, power, and warmth."},
 {q:"What does presence mean?", o:["Speaking loudly","Giving full attention to the moment","Dressing sharply"], a:1, w:"Presence is being fully attentive to the person in front of you."},
 {q:"Power without warmth often feels?", o:["Cold or intimidating","Very friendly","Humble"], a:0, w:"Capability alone can come across as distant."},
 {q:"How do you handle a harsh inner critic?", o:["Argue with it for ten minutes","Notice it as a thought and let it pass","Pretend it does not exist"], a:1, w:"Labeling thoughts reduces their grip without feeding them."}
]},
{ id:"pe06", cat:"people", e:"📘", title:"How to Win Friends", sub:"Core ideas from Dale Carnegie, in plain words", cards:[
 {e:"🙅", h:"Do not criticize or condemn", t:"Carnegie noted that criticism makes people defensive and rarely changes them. Before pointing out a flaw, ask what is going on from their side. Curiosity opens more doors than blame ever will."},
 {e:"🙏", h:"Give honest appreciation", t:"Everyone craves feeling valued. Offer specific, sincere praise rather than flattery. Example: 'The way you explained that to the new hire made her relax, thank you.' Specific beats generic every time."},
 {e:"🎣", h:"Talk in their interests", t:"People care most about what matters to them. Learn what lights someone up and ask about it. Starting there makes conversation easy and shows you see them, not just your own agenda."},
 {e:"📛", h:"Remember their name", t:"A person's name is the most important sound to them. Repeat it once when you meet, connect it to an image, and use it naturally later. 'Good to see you, Maya' shows respect."},
 {e:"😄", h:"Smile and be interested", t:"Being genuinely interested in others earns more friendship in two months than trying to interest them in yourself in two years, as the book puts it. Real curiosity is attractive."},
 {e:"👂", h:"Be a good listener", t:"Encourage others to talk about themselves and listen closely. People rarely forget someone who made them feel heard. Ask follow-ups, and resist waiting for your turn to speak."},
 {e:"🤲", h:"Let them save face", t:"When someone is wrong, avoid public correction. Offer a private, respectful route to adjust. 'Maybe I explained it badly, here is another angle' keeps dignity intact and makes change easier."},
 {e:"⚠️", h:"Sincerity, not technique", t:"These principles work only when genuine. Used as manipulation tricks they backfire, because people sense it. Practice them as a way of caring about others, and results come as a side effect."}
], quiz:[
 {q:"Why does Carnegie advise against criticism?", o:["It makes people defensive and rarely changes them","It is always rude","It hurts your reputation only"], a:0, w:"Criticism triggers defensiveness rather than growth."},
 {q:"What sound matters most to a person?", o:["Their laugh","Their nickname","Their own name"], a:2, w:"Using someone's name shows respect and attention."},
 {q:"How should you give praise?", o:["Specific and sincere","Loud and public always","Vague but frequent"], a:0, w:"Specific appreciation feels real and valued."},
 {q:"What makes these principles backfire?", o:["Practicing too often","Using them insincerely as tricks","Using them with strangers"], a:1, w:"People sense insincerity; genuine interest is essential."}
]},
{ id:"pe07", cat:"people", e:"🤝", title:"Negotiation: Never Split the Difference", sub:"Tactical empathy from Chris Voss, used ethically", cards:[
 {e:"🧠", h:"Negotiation is empathy first", t:"Voss, a former FBI hostage negotiator, argues that understanding the other side's feelings and needs is the path to better deals. You are not weakening your position; you are gathering information."},
 {e:"🪞", h:"Mirror to learn more", t:"Repeat the last one to three words they said with a curious tone. They are likely to elaborate. Example: 'The budget is tight.' You: 'Tight?' It draws out detail without you pushing."},
 {e:"🏷️", h:"Label the emotion", t:"Name the feeling you hear: 'It sounds like you are worried about the timeline.' Labeling lowers tension and shows you understand. Start with 'It seems like' or 'It sounds like', never 'I'.", list:["It sounds like...","It seems like...","It looks like..."]},
 {e:"🎯", h:"Aim for 'That is right'", t:"When you summarize someone's position so well they say 'that is right,' they feel understood and become open to your ideas. It is a stronger signal than a polite 'you are right.'"},
 {e:"🙅", h:"No is not a failure", t:"People feel safer when they can say no. Ask 'Is now a bad time?' or 'Would it be ridiculous to...?' A no protects their autonomy and often leads to more honest discussion."},
 {e:"❓", h:"Ask calibrated questions", t:"Use 'how' and 'what' questions to let them solve your problem. 'How can we make this work for both of us?' invites collaboration, while 'why' can sound accusing and trigger defensiveness."},
 {e:"💰", h:"Prepare your range", t:"Know your goal and your walk-away point before negotiating. Anchoring on researched numbers is fair when honest. Avoid bluffing about facts; trust is your long-term currency in negotiation."},
 {e:"🏁", h:"Seek real win-win", t:"Splitting the difference often leaves both unhappy. Explore what each side actually cares about, such as time, flexibility, or recognition. Creative trades can satisfy both without anyone being deceived."}
], quiz:[
 {q:"What does mirroring involve?", o:["Imitating their posture","Repeating their last few words as a question","Agreeing with everything"], a:1, w:"Mirroring prompts them to elaborate."},
 {q:"What does labeling do?", o:["Accuses them of an emotion","Ends the discussion","Names their feeling to build understanding"], a:2, w:"Labeling shows you hear the emotion and lowers tension."},
 {q:"Why are 'how' questions useful?", o:["They invite collaboration without accusation","They trap the other person","They end negotiation fast"], a:0, w:"Calibrated questions let them help solve the problem."},
 {q:"Which is an ethical negotiating practice?", o:["Inventing fake rival offers","Preparing your range and being honest","Hiding all your needs always"], a:1, w:"Honest preparation sustains trust."}
]},
{ id:"pe08", cat:"people", e:"🗣️", title:"Crucial Conversations", sub:"High-stakes talks without blowing up", cards:[
 {e:"🚨", h:"Spot the crucial moment", t:"A crucial conversation has high stakes, strong emotions, and differing opinions. Learn to notice your own warning signs, like a tight chest or rising voice, so you can slow down before saying something you regret."},
 {e:"🎯", h:"Start with heart", t:"Before speaking, ask what you really want for yourself, the other person, and the relationship. Clarifying your goal stops you from turning the talk into a fight to win."},
 {e:"🏊", h:"Keep the pool of meaning", t:"Great dialogue means everyone feels safe adding their views to a shared pool of meaning. The aim is not to push your view, but to get all views, including disagreements, out into the open."},
 {e:"🛡️", h:"Watch for safety", t:"When people feel unsafe they go silent or attack. If the talk turns tense, step out of the content and restore safety: clarify respect and shared purpose before returning to the topic."},
 {e:"⚖️", h:"Contrast to fix", t:"If someone misreads your intent, use 'don't/do' framing. 'I do not want you to think I doubt your work. I do want us to hit this deadline together.' It removes the false story fast."},
 {e:"🧐", h:"Separate fact from story", t:"Facts are observable; stories are your interpretations. Notice the story you are telling, like 'He ignores me because he disrespects me.' Then ask what else could be true before reacting.", list:["See and hear","Get the facts","Tell the story","Test it"]},
 {e:"💬", h:"State your path gently", t:"Share your facts first, then your view, tentatively but honestly. 'I noticed the report was late twice. I am worried about the client. Can you tell me how you see it?' Invite their perspective."},
 {e:"📝", h:"Close with action", t:"End every crucial talk with who does what by when, and how you will follow up. Without it, good talks evaporate. Write it down so nothing is assumed."}
], quiz:[
 {q:"What defines a crucial conversation?", o:["Low stakes, calm tone","High stakes, strong emotions, opposing views","Only workplace meetings"], a:1, w:"High stakes plus emotions plus disagreement define them."},
 {q:"What should you do when others feel unsafe?", o:["Push harder on content","End the talk forever","Restore safety through respect and shared purpose"], a:2, w:"Safety must exist before honest dialogue can continue."},
 {q:"What is a story in this model?", o:["An interpretation you add to facts","The facts themselves","A joke to ease tension"], a:0, w:"Stories are meanings we assign, separate from observable facts."},
 {q:"How should a crucial talk end?", o:["Silence","Clear actions, owners, and follow-up","With an apology only"], a:1, w:"Concrete next steps prevent the talk from fading away."}
]},
{ id:"pe09", cat:"people", e:"🧭", title:"Influence, Ethically", sub:"Cialdini's principles as a guide, not a trick", cards:[
 {e:"🔁", h:"Reciprocity", t:"People feel inclined to return favors. Genuinely helping first, with no strings attached, builds goodwill naturally. Used honestly it is generosity; used to trap someone into a debt, it is manipulation."},
 {e:"🔒", h:"Commitment and consistency", t:"People like to act in line with what they have said before. Invite small, voluntary commitments and let them follow through. Never trick someone into a stance, because forced consistency erodes trust."},
 {e:"👥", h:"Social proof", t:"We look to what others do when uncertain. It is fair to share true information: 'Most of the team has already joined the new tool.' Never invent testimonials or inflated numbers."},
 {e:"💛", h:"Liking", t:"We say yes more often to people we like. Similarity, compliments, and cooperation build liking. Be honest, since forced charm feels fake. Real shared interest and sincere praise do the work."},
 {e:"🎓", h:"Authority", t:"People defer to credible experts. Make your expertise clear through facts, experience, or sources rather than titles alone. Introduce yourself with relevant background so listeners can judge fairly."},
 {e:"⏳", h:"Scarcity", t:"Rare or limited things seem more valuable. If something truly is limited, say so plainly. Fake deadlines and false 'only two left' claims are deceptive and damage trust the moment someone notices."},
 {e:"🤝", h:"Unity", t:"Added in the later edition, unity is the shared identity: 'we' are in this together. Lean on real common ground, like community or goals, and avoid manufacturing us-versus-them divisions."},
 {e:"🛡️", h:"Use it to defend yourself", t:"Knowing these levers helps you resist pressure. If you feel rushed, flattered, or pushed by 'everyone is doing it', pause and ask: would I decide this way if the pressure was gone?"}
], quiz:[
 {q:"What does reciprocity describe?", o:["Disliking favors","Feeling inclined to return a favor","Refusing gifts"], a:1, w:"People tend to repay kindness."},
 {q:"Which is an ethical use of scarcity?", o:["Inventing a fake countdown","Claiming stock is low when it is not","Stating a real deadline honestly"], a:2, w:"True limits can be shared; false claims deceive."},
 {q:"What is social proof?", o:["Looking to others' behavior when uncertain","A legal contract","Copying nobody"], a:0, w:"We often follow what others do in unclear situations."},
 {q:"How can knowing these principles protect you?", o:["It lets you ignore everyone","It helps you notice pressure and pause","It makes you immune to emotion"], a:1, w:"Awareness lets you slow down before deciding."}
]},
{ id:"pe10", cat:"people", e:"💗", title:"Nonviolent Communication", sub:"Marshall Rosenberg's four steps for hard talks", cards:[
 {e:"🧱", h:"Four parts", t:"Rosenberg's model has four parts: observations, feelings, needs, and requests. Together they let you express yourself honestly without blame, and help you hear others without taking attacks personally."},
 {e:"👁️", h:"Observe without evaluating", t:"State what you saw or heard like a camera would, free of judgment. Say 'You arrived at 7:30 and we started at 7' rather than 'You are always late.' Facts invite listening; labels invite defense."},
 {e:"❤️", h:"Name your feelings", t:"Use real feeling words like worried, hurt, relieved, or excited, not thoughts disguised as feelings, like 'I feel ignored.' That one is a judgment about them. Try 'I feel lonely.'"},
 {e:"🌱", h:"Connect to needs", t:"Behind each feeling is a need, such as respect, rest, connection, or clarity. Naming it moves the talk from fault to meaning. 'I feel anxious because I need predictability' is easier to meet."},
 {e:"🙋", h:"Make a clear request", t:"Ask for something specific, doable, and positive. Not 'Stop being so messy' but 'Would you be willing to put your dishes in the dishwasher after dinner?' A request leaves room for a no.", list:["Observation","Feeling","Need","Request"]},
 {e:"🔎", h:"Hear the need behind it", t:"When someone attacks, guess their feeling and need rather than defending. 'Are you feeling overwhelmed and needing support?' Empathy cools heated moments and shows you are on the same side."},
 {e:"🚫", h:"Requests, not demands", t:"If you punish a no, it was a demand. True requests accept refusal and explore alternatives. That openness is what makes people want to say yes, since their choice is respected."},
 {e:"🌟", h:"Appreciation, same shape", t:"Use the same structure for gratitude: what they did, how you feel, which need it met. 'When you stayed to help, I felt relieved because I needed support.' It lands deeper than 'thanks.'"}
], quiz:[
 {q:"What are the four parts of NVC?", o:["Observation, feeling, need, request","Anger, blame, fix, forget","Listen, nod, agree, leave"], a:0, w:"The four steps are observations, feelings, needs, and requests."},
 {q:"Which is an observation?", o:["You are lazy","You never listen","The dishes were in the sink this morning"], a:2, w:"Observations are factual and free of evaluation."},
 {q:"What separates a request from a demand?", o:["Tone only","A request accepts a no","The use of please"], a:1, w:"If refusal is punished, it was a demand."},
 {q:"When someone attacks you, NVC suggests?", o:["Counterattack","Leave immediately","Guess their feelings and needs"], a:2, w:"Empathic guessing de-escalates and reveals the real need."}
]},
{ id:"pe11", cat:"people", e:"🛑", title:"Assertiveness and Saying No", sub:"Respect yourself and others together", cards:[
 {e:"⚖️", h:"Three communication styles", t:"Passive gives up your needs, aggressive tramples others' needs, and assertive respects both. Assertiveness is clear and kind: stating what you think and want while allowing others to do the same."},
 {e:"🙅", h:"No is a complete sentence", t:"You may explain, but you do not owe a long defense. Short and kind works best. Example: 'Thanks for asking, but I can't take that on right now.' Over-explaining invites negotiation."},
 {e:"🧊", h:"Pause before you answer", t:"Many people say yes on autopilot. Buy time with 'Let me check my calendar and get back to you.' A pause turns a pressured reflex into a chosen decision.", list:["Let me think about it.","I'll check and get back to you.","I need to sleep on that."]},
 {e:"🔊", h:"Use 'I' statements", t:"Describe your view without attacking: 'I feel stretched when the deadline moves without notice' lands better than 'You always change things.' Focus on behavior and impact, not character."},
 {e:"🔁", h:"Broken record technique", t:"If someone keeps pushing, calmly repeat your point in the same words. 'I understand, and I still can't do Saturday.' Repetition without heat shows the answer is settled."},
 {e:"🤝", h:"Offer an alternative if you want", t:"You can decline the request but suggest what you can do: 'I can't lead it, but I can review the draft Thursday.' Only offer what you genuinely want to give, not guilt-driven compromises."},
 {e:"💓", h:"Expect the guilt", t:"Saying no feels uncomfortable at first, and that discomfort does not mean you are wrong. It fades with practice. Remember that every yes to something unwanted is a no to something you value."},
 {e:"🛠️", h:"Practice low stakes first", t:"Start with small refusals, like declining an upsell or a second helping. Build the muscle where it costs little, then use it with bigger asks from colleagues, friends, or family."}
], quiz:[
 {q:"What is assertiveness?", o:["Winning every argument","Respecting your needs and others' together","Staying silent"], a:1, w:"Assertiveness balances honesty with respect."},
 {q:"What is a good response to a request when pressured?", o:["Say yes now, regret later","Argue until they stop","Ask for time to check and answer later"], a:2, w:"A pause turns reflex into choice."},
 {q:"What does the broken record technique involve?", o:["Calmly repeating your position","Raising your voice","Changing your answer"], a:0, w:"Calm repetition signals the decision is final."},
 {q:"If you feel guilty after saying no, it means?", o:["You did something wrong","Nothing about your choice, it's normal discomfort","You must reverse it"], a:1, w:"Guilt often follows new boundaries and fades with practice."}
]},
{ id:"pe12", cat:"people", e:"🔧", title:"Giving and Receiving Feedback", sub:"Say the hard thing so it helps", cards:[
 {e:"🎯", h:"Know your purpose", t:"Before giving feedback, ask: do I want to help this person improve, or to vent? Starting from care makes your tone different, and people can usually tell which one they are getting."},
 {e:"⏱️", h:"Be timely and private", t:"Give feedback soon after the event, in private for critical points. Praise can be public, but correction in front of others stings and triggers defensiveness rather than learning."},
 {e:"📏", h:"Describe, don't judge", t:"Anchor feedback in specific behavior and its effect. 'In the meeting you interrupted Sam twice, and she stopped sharing ideas' is useful. 'You are rude' is not, and it attacks identity.", list:["Situation","Behavior","Impact","Ask or request"]},
 {e:"🥪", h:"Skip the sandwich habit", t:"Wrapping criticism in fluffy praise can hide the point. Be warm but direct: say what worked, what to change, and why it matters. Clarity is a kindness when delivered gently."},
 {e:"❓", h:"Invite their view", t:"Ask 'How did you see it?' before concluding. They may have context you lack. Feedback as a two-way conversation gets better results than a verdict handed down."},
 {e:"🛡️", h:"Receiving: breathe first", t:"When criticized, defensiveness is normal. Take a breath, say 'Thanks for telling me,' and listen fully before replying. You can disagree later; first make sure you understand."},
 {e:"🔍", h:"Look for the useful kernel", t:"Even clumsy feedback may hold a grain of truth. Ask for examples: 'Can you give me one recent case?' Sort what helps from what does not, without taking it as a verdict on your worth."},
 {e:"✅", h:"Follow up on both sides", t:"After receiving feedback, tell the giver what you changed. After giving, check in and notice improvements. Closing the loop encourages honest feedback in future and shows the effort mattered."}
], quiz:[
 {q:"Which is better feedback?", o:["You are careless","You always mess up","The report had three typos that confused the client"], a:2, w:"Specific behavior and impact are actionable."},
 {q:"Where should critical feedback be given?", o:["In private","In front of the team","In a group chat"], a:0, w:"Private correction reduces defensiveness and shame."},
 {q:"What should you do first when receiving criticism?", o:["Defend yourself immediately","Breathe and listen fully","Counter with their faults"], a:1, w:"Listening first helps you separate useful points from defensiveness."},
 {q:"Why invite the other person's view?", o:["To delay the point","To avoid responsibility","They may have context you lack"], a:2, w:"Two-way feedback is more accurate and more effective."}
]},
{ id:"pe13", cat:"people", e:"📖", title:"Storytelling That Connects", sub:"Make your words stick", cards:[
 {e:"🧠", h:"Stories beat facts", t:"Humans remember stories far better than lists of facts. A short story gives listeners a picture and emotion to hold onto. Wrap your key point inside a moment that really happened."},
 {e:"🏗️", h:"Simple structure", t:"Use a basic arc: a situation, a problem or tension, and a resolution. 'I was nervous at my first talk, my slides crashed, and I learned to speak without them.' Short beats long.", list:["Set the scene","Introduce the problem","Show the turning point","Land the lesson"]},
 {e:"🎬", h:"Start in the middle", t:"Open with a moment, not a preamble. 'The elevator doors closed and I realized I had no badge' hooks faster than 'So last Tuesday I was at work.' Cut background that does not serve the point."},
 {e:"👀", h:"Use concrete details", t:"One vivid detail beats five vague ones. Say 'the coffee had gone cold in my hands' rather than 'I was stressed.' Specifics help listeners see and feel the moment themselves."},
 {e:"💔", h:"Include a struggle", t:"Stories about everything going perfectly bore people. Showing a mistake or doubt makes you relatable and trustworthy. Vulnerability within reason invites others to open up in return."},
 {e:"🎯", h:"Know the point", t:"Before telling a story, know why you are telling it. If you cannot name the takeaway in a sentence, trim or skip it. A story that serves the conversation is welcome; one that hijacks it is not."},
 {e:"🗣️", h:"Mind your delivery", t:"Vary pace and volume, pause before the key moment, and let your face show the feeling. Practice out loud once. A well-timed silence before the punchline often matters more than the words."},
 {e:"📚", h:"Collect your stories", t:"Keep a short list of personal stories: a mistake, a funny travel moment, a lesson learned. Having three or four ready lowers anxiety and lets you contribute naturally in social or work settings."}
], quiz:[
 {q:"What is a simple story structure?", o:["Lecture, list, summary","Situation, tension, resolution","Joke, joke, joke"], a:1, w:"A basic arc keeps listeners engaged."},
 {q:"Where should a story start?", o:["With a long background","With the moral","In an interesting moment"], a:2, w:"Opening mid-moment hooks attention."},
 {q:"Why include a struggle?", o:["It makes you relatable and credible","To seem humble falsely","To make it longer"], a:0, w:"Real challenges build trust and interest."},
 {q:"What should you know before telling a story?", o:["Nothing, wing it","How long it can run","The point you want to make"], a:2, w:"A clear takeaway keeps the story purposeful."}
]},
{ id:"pe14", cat:"people", e:"🌿", title:"Handling Social Anxiety", sub:"Gentle, practical ways to feel safer around people", cards:[
 {e:"🧠", h:"Anxiety is common", t:"Most people feel nervous in social settings at times. Anxiety is your brain trying to protect you from judgment. Knowing it is normal and treatable takes away the extra shame about feeling anxious."},
 {e:"🔭", h:"Shift focus outward", t:"Anxious minds watch themselves: how do I look, what am I saying? Redirect attention to the room and the person. Ask yourself, 'What are they feeling? What are they saying?' Self-focus fuels fear."},
 {e:"🪜", h:"Climb a ladder", t:"Avoiding what scares you keeps the fear alive. List social situations from least to most scary and tackle them step by step. Say hello to a neighbor first; a party comes later.", list:["Greet a cashier","Ask a stranger for directions","Chat with a coworker","Attend a small gathering"]},
 {e:"🌬️", h:"Slow your breathing", t:"Breathe in for four counts and out for six. Longer exhales calm the body. Use it before walking in and during pauses. A calmer body makes it easier to think clearly and speak naturally."},
 {e:"🔍", h:"Test your predictions", t:"Anxiety predicts disaster: 'They will think I'm boring.' Treat it like an experiment. Note what you expected, then what actually happened. Most feared outcomes never happen, and evidence slowly rewires beliefs."},
 {e:"🔦", h:"The spotlight effect", t:"We think others notice our flaws far more than they do. Research shows people greatly overestimate how visible their mistakes are. Most people are too busy worrying about themselves to judge you harshly.", stat:{n:"~50%", l:"of observers notice what we think they do, per classic spotlight-effect studies by Gilovich"}},
 {e:"🤗", h:"Be kind to yourself", t:"Talk to yourself as you would to a friend. 'That was awkward, and it is okay, I'm learning' beats harsh self-criticism. Self-compassion lowers fear of mistakes and makes trying again easier."},
 {e:"🩺", h:"Seek help when needed", t:"If anxiety stops you from work, relationships, or daily life, consider talking to a therapist. Cognitive behavioral therapy has strong evidence for social anxiety. Asking for help is a strength, not a failure."}
], quiz:[
 {q:"What does avoiding feared situations usually do?", o:["Reduces anxiety long term","Keeps the fear alive","Cures it quickly"], a:1, w:"Avoidance reinforces fear by preventing new evidence."},
 {q:"What is a helpful attention shift?", o:["Watch your own flaws","Rehearse mistakes","Focus on the other person and surroundings"], a:2, w:"External focus reduces self-monitoring and anxiety."},
 {q:"What is the spotlight effect?", o:["Overestimating how much others notice our flaws","Being the center of attention","A lighting technique"], a:0, w:"We assume others notice us more than they do."},
 {q:"Which therapy has strong evidence for social anxiety?", o:["Cognitive behavioral therapy","Avoidance training","Ignoring symptoms"], a:0, w:"CBT is well researched and effective."}
]},
{ id:"pe15", cat:"people", e:"💞", title:"Deep Friendship and Authentic Dating", sub:"Closeness built on honesty and respect", cards:[
 {e:"🌊", h:"Depth comes from disclosure", t:"Close bonds grow when two people gradually share more personal things and the other responds with care. Share a small real thing, watch the reaction, and let trust set the pace."},
 {e:"🔄", h:"Reciprocity of openness", t:"Vulnerability works when it goes both ways. Share something a little deeper than they did, rather than dumping your biggest secrets early. Steady, matching steps feel safe for both of you."},
 {e:"📞", h:"Keep in touch", t:"Friendships fade without contact. Send a quick text when someone crosses your mind: 'Saw this and thought of you.' Small, regular check-ins matter more than rare grand gestures.", list:["Remember key dates","Send a random check-in","Plan a recurring catch-up"]},
 {e:"🛠️", h:"Show up in hard times", t:"Friends are made in difficulty. Offer specific help instead of 'let me know if you need anything.' Try 'I can bring dinner Thursday, does that work?' Specificity makes it easy to accept."},
 {e:"🧭", h:"Dating: be honest and curious", t:"Attraction grows from genuine interest, humor, and ease, not scripts. Be yourself, ask real questions, and share your actual interests. Pretending to be someone else only attracts people to a fiction."},
 {e:"✅", h:"Consent and clarity", t:"Respect is non-negotiable. Ask before touching, accept a no without pressure, and be clear about your intentions. 'I like spending time with you, would you like to go on a date?' is direct and kind."},
 {e:"🚦", h:"Read interest, don't push", t:"Look for mutual signals: they reply, make time, and ask about you. If interest seems low, step back gracefully. A gracious 'no worries, take care' leaves everyone's dignity intact."},
 {e:"🌱", h:"Repair after rifts", t:"Every close relationship hits a snag. Repair with a clear apology: what you did, its impact, and what you will change. 'I'm sorry I forgot, it hurt you, I will set a reminder' rebuilds trust."}
], quiz:[
 {q:"How does closeness usually deepen?", o:["Sharing everything at once","Gradual, mutual disclosure","Staying surface-level"], a:1, w:"Trust grows through matched, step-by-step openness."},
 {q:"Which offer of help is most effective?", o:["Let me know if you need anything","I can bring dinner Thursday","I hope it gets better"], a:1, w:"Specific offers are easier to accept."},
 {q:"What should you do if someone says no to a date?", o:["Argue your case","Keep asking daily","Accept it gracefully"], a:2, w:"Respecting a no protects dignity on both sides."},
 {q:"What does a good apology include?", o:["The impact and what you will change","A long excuse","Blaming circumstances"], a:0, w:"Naming the impact and a change rebuilds trust."}
]},
{ id:"pe16", cat:"people", e:"🌐", title:"Networking and Leading Conversations", sub:"Build relationships and communicate as a leader", cards:[
 {e:"🌱", h:"Networking is relationships", t:"Think of networking as building genuine relationships over time, not collecting contacts. Aim to be curious and useful. People remember those who made them feel respected, long after they forget a business card."},
 {e:"🎁", h:"Give before you ask", t:"Share an article, make an introduction, or offer a skill before you need anything. Generosity builds goodwill without keeping score. Example: 'You mentioned hiring, I know someone who might fit.'"},
 {e:"🧠", h:"Weak ties matter", t:"Research by sociologist Mark Granovetter found that acquaintances often bring new opportunities, like jobs, since they connect you to different circles. Keep in light touch with a wide set of people."},
 {e:"✉️", h:"Write a clear outreach", t:"Keep first messages short, specific, and easy to answer. 'I enjoyed your talk on data teams. Could I ask two quick questions about getting started? Happy to keep it to 15 minutes.'"},
 {e:"📆", h:"Follow up and stay warm", t:"After meeting someone, send a note within two days referencing something you discussed. Then check in a few times a year with something useful. Consistency is what turns contacts into allies."},
 {e:"🧭", h:"Lead with clarity", t:"Leaders communicate the why, the what, and the what next. State the goal, the reason it matters, and who does what. Ambiguity breeds anxiety, while clarity lets people act with confidence."},
 {e:"👂", h:"Ask, then decide", t:"Strong leaders invite input before deciding. 'What risks do you see?' and 'What am I missing?' surface insight and build buy-in. Once you decide, explain your reasoning so people can commit.", list:["What risks do you see?","What am I missing?","What would you do?"]},
 {e:"🏅", h:"Credit loudly, own errors", t:"Publicly credit others' contributions by name and specifics, and take responsibility when things go wrong. This builds psychological safety, which makes teams speak up early and learn faster."}
], quiz:[
 {q:"What is a good networking mindset?", o:["Collect as many cards as possible","Build genuine relationships and be useful","Only contact people when you need help"], a:1, w:"Long-term goodwill outperforms transactional contact."},
 {q:"Why are weak ties valuable?", o:["They link you to new circles","They are closer than friends","They cost nothing to keep"], a:0, w:"Acquaintances bridge different networks and opportunities."},
 {q:"What makes a good outreach message?", o:["Long, with your life story","Vague and open-ended","Short, specific, easy to answer"], a:2, w:"Specific small asks are easier to respond to."},
 {q:"How should a leader handle credit and blame?", o:["Take credit, assign blame","Credit others, own mistakes","Stay silent on both"], a:1, w:"Giving credit and owning errors builds trust and safety."}
]}
);
window.TIPS.push(
{cat:"people", e:"💡", h:"Name it to tame it", t:"Saying 'I'm a bit nervous' out loud often calms you and makes others warmer toward you."},
{cat:"people", e:"💡", h:"Ask a follow-up", t:"The question after the question is where real conversation starts. Pick a detail and say, 'Tell me more about that.'"},
{cat:"people", e:"💡", h:"Use their name", t:"Say a person's name once early in the talk. It shows attention and helps you remember it."},
{cat:"people", e:"💡", h:"Phone down", t:"A phone face down on the table says 'you matter.' One on top says the opposite."},
{cat:"people", e:"💡", h:"Praise the specific", t:"'Great job' fades. 'The way you handled that angry customer was calm and kind' is remembered."},
{cat:"people", e:"💡", h:"Pause before replying", t:"Two seconds of silence makes you sound thoughtful and gives the other person room to add more."},
{cat:"people", e:"💡", h:"Be the first to say hi", t:"Most people wait to be greeted. Taking the first step instantly marks you as friendly."},
{cat:"people", e:"💡", h:"Skip the humble-brag", t:"Be honest about wins in plain words. Fake modesty gets noticed and trusted less."},
{cat:"people", e:"💡", h:"Match the energy, then guide", t:"Meet someone's tone first, then slowly shift it calmer or brighter. Fighting their mood head-on backfires."},
{cat:"people", e:"💡", h:"Curiosity beats cleverness", t:"You do not need witty lines. Real interest in the other person is more attractive than any rehearsed joke."},
{cat:"people", e:"💡", h:"Reply to the feeling", t:"When someone vents, respond to the emotion before the facts. 'That sounds exhausting' comes before any advice."},
{cat:"people", e:"💡", h:"Invite, don't wait", t:"Friendships start with an invite. Send one small, specific plan this week."},
{cat:"people", e:"💡", h:"Feet point to interest", t:"People often angle their feet toward what interests them. Angle yours toward the person you are talking to."},
{cat:"people", e:"💡", h:"Soften with 'and'", t:"Replace 'but' with 'and' when giving feedback. 'You did well, and here is one thing to improve' lands softer."},
{cat:"people", e:"💡", h:"Say it kindly, say it once", t:"Make your request clear and calm one time. Nagging weakens the message and strains the relationship."},
{cat:"people", e:"💡", h:"Do not interrupt", t:"Let people finish. If you fear forgetting your point, jot a word down and wait."},
{cat:"people", e:"💡", h:"End on a high", t:"People remember how conversations end. Close warmly with 'Really enjoyed this' before you leave."},
{cat:"people", e:"💡", h:"Make 'no' friendly", t:"'Thanks for thinking of me, I can't this time' is polite, clear, and needs no further excuse."},
{cat:"people", e:"💡", h:"Check intent before reacting", t:"Before getting upset, ask: 'Did you mean it that way?' Many hurts are misunderstandings."},
{cat:"people", e:"💡", h:"Three-sentence rule", t:"If your story is not done in about three sentences, check whether the listener is still with you."},
{cat:"people", e:"💡", h:"Mirror their last words", t:"Repeating their final few words as a question invites them to say more without any pressure."},
{cat:"people", e:"💡", h:"Warm first, then direct", t:"Open with a sentence of care before a hard message. It lowers defenses without watering down the point."},
{cat:"people", e:"💡", h:"Practice with low stakes", t:"Chat with a barista or neighbor. Small daily reps build social confidence for bigger moments."},
{cat:"people", e:"💡", h:"Remember small details", t:"Note a person's pet, project, or upcoming trip. Asking about it next time feels like real care."},
{cat:"people", e:"💡", h:"Silence is okay", t:"A few seconds of quiet is not failure. Comfortable silence is a sign of ease with someone."},
{cat:"people", e:"💡", h:"Fix the problem, not the person", t:"In conflict, attack the issue together. 'How do we solve this?' beats 'Why are you like this?'"},
{cat:"people", e:"💡", h:"Smile with your eyes", t:"Think of something you like about the person and a real smile follows naturally."},
{cat:"people", e:"💡", h:"Speak slower", t:"Slowing down makes you sound calmer and more confident, and helps others follow you."},
{cat:"people", e:"💡", h:"Give a sincere compliment", t:"Notice a choice, not just a look: 'Great taste in books.' It says you paid attention."},
{cat:"people", e:"💡", h:"Don't diagnose, describe", t:"Say 'The report was late twice' rather than 'You're unreliable.' Behavior can change; labels stick."},
{cat:"people", e:"💡", h:"Ask for advice", t:"'What would you do here?' flatters sincerely, builds connection, and often gives you good ideas."},
{cat:"people", e:"💡", h:"Reconnect without guilt", t:"Skip the long apology for going quiet. 'Been thinking of you, want to catch up?' works well."},
{cat:"people", e:"💡", h:"Offer specific help", t:"Replace 'let me know if you need anything' with 'I can bring dinner Thursday.' Specific offers get accepted."},
{cat:"people", e:"💡", h:"Face anxiety gradually", t:"Take one small social step each day. Gradual exposure shrinks fear far better than avoidance."},
{cat:"people", e:"💡", h:"Nobody is watching closely", t:"Most people overestimate how much others notice their slip-ups. Others are busy worrying about themselves."},
{cat:"people", e:"💡", h:"Text less, call more", t:"For emotional topics, voice beats text. Tone prevents the misreadings that written words invite."},
{cat:"people", e:"💡", h:"Two ears, one mouth", t:"Aim to listen about as much as you talk, or more. People leave feeling good about those who listen."},
{cat:"people", e:"💡", h:"Public praise, private critique", t:"Celebrate people in front of others and correct them one on one. Dignity builds trust."},
{cat:"people", e:"💡", h:"Don't win the argument", t:"If winning costs the relationship, you lost. Aim to understand before aiming to persuade."},
{cat:"people", e:"💡", h:"Send the intro", t:"Introduce two people who should meet, with one line on why. Connecting others is the best networking move."},
{cat:"people", e:"💡", h:"Use 'I' statements", t:"'I feel worried when plans change late' invites listening. 'You always change plans' invites defense."},
{cat:"people", e:"💡", h:"Check what they need", t:"Ask 'Do you want advice or just support?' It prevents the most common listening mistake."},
{cat:"people", e:"💡", h:"Be consistent, not perfect", t:"Reliable small gestures beat rare grand ones. Show up on time, reply, and keep your word."},
{cat:"people", e:"💡", h:"Own your mistakes fast", t:"A quick, specific apology earns more respect than a polished excuse. Say what happened and what you will change."},
{cat:"people", e:"💡", h:"Respect a no", t:"Whether in dating, friendship, or work, accepting a no gracefully makes people trust your yes."},
{cat:"people", e:"💡", h:"Start with a goal", t:"Before a tough talk, decide what you want for you, them, and the relationship. It keeps you calm and focused."},
{cat:"people", e:"💡", h:"Label tension", t:"'It seems like this is stressful for you' defuses heat faster than arguing the facts."},
{cat:"people", e:"💡", h:"Keep intros short", t:"Introduce yourself in one clear sentence plus a hook, like 'I'm Sam, I design board games.' It invites questions."},
{cat:"people", e:"💡", h:"Be hard on issues, soft on people", t:"You can disagree firmly while still showing respect. Both can coexist."},
{cat:"people", e:"💡", h:"Share a small struggle", t:"Admitting a minor mistake makes you relatable. People trust those who are not pretending to be perfect."},
{cat:"people", e:"💡", h:"Send a thank-you", t:"A two-line note after someone helps you stands out, because few people bother."},
{cat:"people", e:"💡", h:"Breathe out longer", t:"Inhale four counts, exhale six before a big conversation. It settles your body quickly."},
{cat:"people", e:"💡", h:"Assume good intent first", t:"Start from the most generous explanation. You will be wrong sometimes, but kinder and calmer always."},
{cat:"people", e:"💡", h:"Follow up within 48 hours", t:"After meeting someone new, message them within two days. Memory and goodwill fade quickly."},
{cat:"people", e:"💡", h:"Ask 'what' not 'why'", t:"'What led to this?' feels open; 'Why did you do that?' can sound accusing."},
{cat:"people", e:"💡", h:"Credit others by name", t:"Say 'Priya's analysis made this possible.' Specific credit builds loyalty and teamwork."},
{cat:"people", e:"💡", h:"Make eye contact in thirds", t:"Meet their eyes about half to two thirds of the time. Look away to think, then return."},
{cat:"people", e:"💡", h:"Do one brave thing", t:"Each week, do one slightly uncomfortable social thing. Courage grows with small, regular practice."},
{cat:"people", e:"💡", h:"Thank the listener", t:"After someone hears you out, say 'Thanks for listening.' It reinforces the habit and deepens trust."},
{cat:"people", e:"💡", h:"Rest after socializing", t:"Introverts and extroverts both need recovery time. Plan quiet time so you can show up well next time."}
);
